package com.yigongbao.backup.job;
import java.time.Duration;
/** 领取并执行单个到期任务。 */
public final class JobDispatcher {private final PersistentJobCoordinator c;private final JobExecutorRegistry r;private final JobEvidenceService evidence;private final String owner;private final long lease;private final int retries;public JobDispatcher(PersistentJobCoordinator c,JobExecutorRegistry r,String owner,Duration lease,int retries){this(c,r,null,owner,lease,retries);}public JobDispatcher(PersistentJobCoordinator c,JobExecutorRegistry r,JobEvidenceService evidence,String owner,Duration lease,int retries){this.c=c;this.r=r;this.evidence=evidence;this.owner=owner;this.lease=lease.toSeconds();this.retries=retries;}public boolean dispatchOne(){JobEntity j=c.claimNext(owner,lease);if(j==null)return false;long token=j.getFencingToken();JobExecutionContext x=new JobExecutionContext(c,evidence,j.getId(),owner,token,lease);try{x.safePoint("STARTED",0);r.required(j.getJobType()).execute(x,j);c.succeed(j.getId(),owner,token);}catch(JobCancelledException ignored){return true;}catch(Throwable failure){x.failure(failure);c.failOrRetry(j.getId(),owner,token,retries,failure);}return true;}}
